<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox, type FormInstance, type FormRules } from 'element-plus'
import { adjustStock, allCategories, createBook, deleteBook, listBooks, updateBook, type BookInput } from '../api/books'
import { errorMessage } from '../utils/errors'
import { validIsbn } from '../utils/validation'
import type { Book, Category } from '../types/domain'
const query = reactive({ title: '', status: 'ACTIVE', ordering: '-created_at', page: 1, page_size: 20 })
const rows = ref<Book[]>([]); const categories = ref<Category[]>([]); const count = ref(0); const loading = ref(false); const dialog = ref(false); const editing = ref<string | null>(null); const saving = ref(false)
const formRef = ref<FormInstance>()
const form = reactive<BookInput>({ title: '', author: '', isbn: '', category: '', publisher: '', published_date: null, description: '', status: 'ACTIVE', total_copies: 0 })
const rules: FormRules = {
  title: [{ required: true, message: '请输入书名', trigger: 'blur' }, { validator: (_rule, value: string, callback: (error?: Error) => void) => value.trim() ? callback() : callback(new Error('书名不能为空白')), trigger: 'blur' }, { max: 200, message: '最多 200 个字符', trigger: 'blur' }],
  author: [{ required: true, message: '请输入作者', trigger: 'blur' }, { validator: (_rule, value: string, callback: (error?: Error) => void) => value.trim() ? callback() : callback(new Error('作者不能为空白')), trigger: 'blur' }, { max: 200, message: '最多 200 个字符', trigger: 'blur' }],
  isbn: [{ required: true, message: '请输入 ISBN', trigger: 'blur' }, { validator: (_rule, value: string, callback: (error?: Error) => void) => validIsbn(value) ? callback() : callback(new Error('ISBN 校验位不正确')), trigger: 'blur' }],
  category: [{ required: true, message: '请选择分类', trigger: 'change' }],
  total_copies: [{ validator: (_rule, value: number, callback: (error?: Error) => void) => Number.isInteger(value) && value >= 0 ? callback() : callback(new Error('库存必须是非负整数')), trigger: 'change' }],
}
const stockDialog = ref(false); const stockBook = ref<Book | null>(null); const stockTotal = ref(0); const stockSaving = ref(false)
async function load() { loading.value = true; try { const data = await listBooks({ title: query.title || undefined, status: query.status, ordering: query.ordering, page: query.page, page_size: query.page_size }); rows.value = data.results; count.value = data.count } catch (error) { ElMessage.error(errorMessage(error)) } finally { loading.value = false } }
async function loadCategories() { try { categories.value = await allCategories() } catch (error) { ElMessage.error(errorMessage(error)) } }
function search() { query.page = 1; void load() }
function open(row?: Book) { editing.value = row?.id ?? null; Object.assign(form, row ? { title: row.title, author: row.author, isbn: row.isbn, category: row.category, publisher: row.publisher, published_date: row.published_date, description: row.description, status: row.status, total_copies: row.total_copies } : { title: '', author: '', isbn: '', category: '', publisher: '', published_date: null, description: '', status: 'ACTIVE', total_copies: 0 }); dialog.value = true }
async function save() { if (!await formRef.value?.validate().catch(() => false)) return; saving.value = true; try { if (editing.value) { const { total_copies: _total, ...payload } = form; await updateBook(editing.value, payload) } else await createBook({ ...form }); ElMessage.success('书目已保存'); dialog.value = false; await load() } catch (error) { ElMessage.error(errorMessage(error)) } finally { saving.value = false } }
async function remove(row: Book) { try { await ElMessageBox.confirm(`确定归档图书「${row.title}」？归档后不能新增借阅。`, '二次确认', { type: 'warning', confirmButtonText: '确认归档', cancelButtonText: '取消' }); await deleteBook(row.id); ElMessage.success('图书已归档'); if (rows.value.length === 1 && query.page > 1) query.page -= 1; await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(errorMessage(error)) } }
function openStock(row: Book) { stockBook.value = row; stockTotal.value = row.total_copies; stockDialog.value = true }
async function saveStock() { if (!stockBook.value) return; const occupied = stockBook.value.total_copies - stockBook.value.available_copies; if (!Number.isInteger(stockTotal.value) || stockTotal.value < occupied) { ElMessage.error(`新总量不能低于已占用的 ${occupied} 册`); return } stockSaving.value = true; try { await adjustStock(stockBook.value.id, stockTotal.value); ElMessage.success('库存已调整'); stockDialog.value = false; await load() } catch (error) { ElMessage.error(errorMessage(error)) } finally { stockSaving.value = false } }
onMounted(() => { void loadCategories(); void load() })
</script>
<template><div class="page-head"><div><h1>图书管理</h1><p>维护书目资料和库存</p></div><el-button type="primary" @click="open()">新增图书</el-button></div><div class="panel"><div class="toolbar"><el-input v-model="query.title" placeholder="书名模糊查询" clearable @keyup.enter="search" /><el-select v-model="query.status"><el-option label="在架" value="ACTIVE" /><el-option label="归档" value="ARCHIVED" /></el-select><el-select v-model="query.ordering" placeholder="排序"><el-option label="最新录入" value="-created_at" /><el-option label="最早录入" value="created_at" /><el-option label="书名升序" value="title" /><el-option label="书名降序" value="-title" /><el-option label="出版日期由新到旧" value="-published_date" /></el-select><el-button type="primary" @click="search">查询</el-button></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="title" label="书名" min-width="180" /><el-table-column prop="author" label="作者" min-width="110" /><el-table-column prop="isbn" label="ISBN" min-width="150" /><el-table-column prop="category_name" label="分类" min-width="100" /><el-table-column label="库存" width="120"><template #default="scope">{{ scope.row.available_copies }} / {{ scope.row.total_copies }}</template></el-table-column><el-table-column prop="status" label="状态" width="95" /><el-table-column label="操作" width="210"><template #default="scope"><el-button link type="primary" @click="open(scope.row)">编辑</el-button><el-button link type="primary" @click="openStock(scope.row)">库存</el-button><el-button v-if="scope.row.status==='ACTIVE'" link type="danger" @click="remove(scope.row)">归档</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="query.page" :page-size="query.page_size" :total="count" layout="total, prev, pager, next" @current-change="load" /></div></div>
<el-dialog v-model="dialog" :title="editing ? '编辑图书' : '新增图书'" width="640px" destroy-on-close><el-form ref="formRef" :model="form" :rules="rules" label-width="100px"><el-form-item label="书名" prop="title"><el-input v-model="form.title" maxlength="200" /></el-form-item><el-form-item label="作者" prop="author"><el-input v-model="form.author" maxlength="200" /></el-form-item><el-form-item label="ISBN" prop="isbn"><el-input v-model="form.isbn" /></el-form-item><el-form-item label="分类" prop="category"><el-select v-model="form.category" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id" /></el-select></el-form-item><el-form-item label="出版社"><el-input v-model="form.publisher" maxlength="200" /></el-form-item><el-form-item label="出版日期"><el-date-picker v-model="form.published_date" type="date" value-format="YYYY-MM-DD" placeholder="选择日期" /></el-form-item><el-form-item v-if="!editing" label="总册数" prop="total_copies"><el-input-number v-model="form.total_copies" :min="0" :max="2147483647" :precision="0" /></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="在架" value="ACTIVE" /><el-option label="归档" value="ARCHIVED" /></el-select></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea" :rows="3" maxlength="10000" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="stockDialog" title="调整总库存" width="420px"><p>图书：{{ stockBook?.title }}</p><p class="muted">当前总量 {{ stockBook?.total_copies }}，已占用 {{ (stockBook?.total_copies ?? 0) - (stockBook?.available_copies ?? 0) }} 册。</p><el-input-number v-model="stockTotal" :min="0" :max="2147483647" :precision="0" /><template #footer><el-button @click="stockDialog=false">取消</el-button><el-button type="primary" :loading="stockSaving" @click="saveStock">保存</el-button></template></el-dialog></template>
